"""Create a standalone, accessible library. No external scripts or services."""
from pathlib import Path
from html import escape
from plan import GUIDES
p=Path(__file__).parent/'publish'
import json, math
pages={}
for slug,(title,duration,scenes) in GUIDES.items():
 timeline=Path(__file__).parent/'voice-janet'/f'{slug}-timeline.json'
 if timeline.exists():
  info=json.loads(timeline.read_text());duration=info['duration']+4.0
  steps=[{'title':b['title'].replace('\n',' '),'narration':b['narration'],'start':b['start']+2.5} for b in info['scenes']]
  media=slug+'-janet-music';voice='Janet · animated steps · music'
 else:
  steps=[{'title':s['title'].replace('\n',' '),'narration':s['narration']} for s in scenes]
  media=slug;voice='Original narration'
 pages[slug]={'title':title,'duration':duration,'scenes':steps,'media':media,'voice':voice}
links=''.join(f'<a href="?guide={slug}"><span>{escape(g["title"])}<br><small>{escape(g["voice"])}</small></span><small>{math.ceil(g["duration"])} sec</small></a>' for slug,g in pages.items())
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nam Illam · Video guides</title><style>
:root{color-scheme:dark;font-family:system-ui,-apple-system,sans-serif;background:#0c0f14;color:#f6f7fa}*{box-sizing:border-box}body{margin:0}main{max-width:1200px;margin:auto;padding:40px 24px}header{border-bottom:1px solid #343c49;padding-bottom:24px;display:flex;justify-content:space-between;gap:16px}a{color:#ffdc61}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid #ffdc61;outline-offset:4px}h1{font-size:clamp(32px,5vw,56px);letter-spacing:-.04em;max-width:900px;line-height:1.07}p{color:#bdc7d6;line-height:1.65}video{width:100%;background:#10151d;border:1px solid #3b4453;border-radius:16px}section{margin-top:28px}.eyebrow{color:#ffdc61;letter-spacing:.1em;font-size:12px;font-weight:700}nav{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}nav a{padding:20px;background:#1b222d;border:1px solid #394352;border-radius:14px;color:white;text-decoration:none;display:flex;justify-content:space-between;gap:16px}nav a[aria-current=page]{border-color:#ffdc61}small{white-space:nowrap;color:#ffdc61}button{border:1px solid #475263;border-radius:10px;background:#202936;color:white;padding:12px 16px;cursor:pointer;font:inherit;text-align:left}#chapters{display:flex;gap:8px;flex-wrap:wrap}details{background:#171e28;padding:20px;border-radius:14px}summary{cursor:pointer;font-weight:650}#transcript h3{margin-bottom:0}footer{margin-top:48px;border-top:1px solid #343c49;padding-top:20px;font-size:14px} @media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style><main><header><strong>NAM ILLAM</strong><a href="https://neuralluna.com/">Visit our website ↗</a></header><p class="eyebrow">LEARN WITH THE APP YOU USE</p><h1 id="title">One purchase. Everything connected.</h1><p>Actual Nam Illam screens, sample household data, and English narration. The two Janet guides include a welcome opening, gentle original music, animated tap cues and guided screen transitions. Pause whenever you want to try a step in your app.</p><video id="video" controls playsinline preload="metadata" poster="connected-kitchen-janet-music.jpg" src="connected-kitchen-janet-music.mp4"><track kind="captions" label="English" srclang="en" src="connected-kitchen-janet-music.vtt">Your browser cannot play this video.</video><p><a id="download" href="connected-kitchen.mp4" download>Download video</a> · <a id="text" href="connected-kitchen.txt">Read the text version</a></p><section aria-label="Video chapters"><h2>Jump to a step</h2><div id="chapters"></div></section><section><details><summary>Read the full transcript</summary><div id="transcript"></div></details></section><section><h2>Explore the guides</h2><nav aria-label="Video guides">LINKS</nav></section><footer><p>Animated walkthroughs use actual screenshots from the Nam Illam v2 preview; tap cues are instructional overlays. Some screens may differ from the current App Store version. Demonstration data only. Narration uses a synthetic English voice. No analytics or external video service.</p><a href="mailto:support@neuralluna.com">support@neuralluna.com</a></footer></main><script>
const guides=DATA;const requested=new URLSearchParams(location.search).get('guide');const slug=Object.hasOwn(guides,requested)?requested:'connected-kitchen';const guide=guides[slug];const video=document.getElementById('video');document.getElementById('title').textContent=guide.title;document.title=guide.title+' · Nam Illam';video.src=guide.media+'.mp4';video.poster=guide.media+'.jpg';video.querySelector('track').src=guide.media+'.vtt';document.getElementById('download').href=guide.media+'.mp4';document.getElementById('text').href=slug+'.txt';document.querySelector('nav a[href="?guide='+slug+'"]').setAttribute('aria-current','page');guide.scenes.forEach((scene,i)=>{const b=document.createElement('button');b.textContent=(i+1)+'. '+scene.title;b.onclick=()=>{video.currentTime=scene.start??(i*guide.duration/guide.scenes.length+0.4);video.focus()};document.getElementById('chapters').append(b);const h=document.createElement('h3');h.textContent=scene.title;const p=document.createElement('p');p.textContent=scene.narration;document.getElementById('transcript').append(h,p)});
</script></html>'''.replace('LINKS',links).replace('DATA',json.dumps(pages))
(p/'index.html').write_text(html)
